import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Wie rechnet der Adapter?","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/05.hintergrund/01.berechnung.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/hintergrund/berechnung.md","filePath":"de/adapter/sourceanalytix/hintergrund/berechnung.md","lastUpdated":null}'),i={name:"de/adapter/sourceanalytix/hintergrund/berechnung.md"};function d(s,e,u,h,l,o){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="wie-rechnet-der-adapter" tabindex="-1">Wie rechnet der Adapter? <a class="header-anchor" href="#wie-rechnet-der-adapter" aria-label="Permalink to &quot;Wie rechnet der Adapter?&quot;">​</a></h1><p><a id="sourceanalytix-still-maintained"></a></p><h2 id="wird-sourceanalytix-noch-weiterentwickelt" tabindex="-1">Wird SourceAnalytix noch weiterentwickelt? <a class="header-anchor" href="#wird-sourceanalytix-noch-weiterentwickelt" aria-label="Permalink to &quot;Wird SourceAnalytix noch weiterentwickelt?&quot;">​</a></h2><p><strong>Kurz:</strong> Ja. Nach einer langen Pause zwischen v0.4.14 (Februar 2022) und v0.5.0 (Juli 2026) erscheinen wieder regelmäßig neue Versionen, zuletzt v0.6.0 am 26.09.2026 und v0.6.1 am 07.11.2026. v0.6.2 bringt Fehlerbehebungen, v0.7.0 die neue Einstellungsseite mit Aktionen zum Korrigieren.</p><p>SourceAnalytix steht derzeit im Repository „latest&quot; (Beta). In „stable&quot; kommt es erst nach einer Testphase. Wie du auf eine neue Version kommst, steht unter <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Wie aktualisiere ich SourceAnalytix?</a>.</p><h3 id="wohin-mit-fragen-und-fehlern" tabindex="-1">Wohin mit Fragen und Fehlern <a class="header-anchor" href="#wohin-mit-fragen-und-fehlern" aria-label="Permalink to &quot;Wohin mit Fragen und Fehlern&quot;">​</a></h3><ol><li>Schau ab v0.7.0 zuerst in den Tab „Probleme&quot; der Instanz-Einstellungen. Er prüft alle Quellen und schlägt eine Lösung vor.</li><li>Lies die Seiten zur <a href="./../fehlerbehebung/">Fehlerbehebung</a>.</li><li>Einen Fehler oder einen Wunsch meldest du als Issue im <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues" target="_blank" rel="noreferrer">GitHub-Repository</a>. Prüfe vorher, ob es schon ein Issue dazu gibt. Gib die Versionen von SourceAnalytix, js-controller und Node.js an und hänge das Log der betroffenen Quelle an.</li></ol><p>Funktionen, die viele sich wünschen, etwa „Datenpunkt wechseln&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>) oder eine „Summe über alle Quellen&quot;, sind als geplant gekennzeichnet. Auf der Einstellungsseite tragen sie den Hinweis „geplant&quot;.</p><p><a id="values-differ-meter-portal-evcc"></a></p><h2 id="warum-weichen-die-werte-von-zahler-portal-oder-evcc-ab" tabindex="-1">Warum weichen die Werte von Zähler, Portal oder evcc ab? <a class="header-anchor" href="#warum-weichen-die-werte-von-zahler-portal-oder-evcc-ab" aria-label="Permalink to &quot;Warum weichen die Werte von Zähler, Portal oder evcc ab?&quot;">​</a></h2><p><strong>Kurz:</strong> Meist hat es einen von vier Gründen: Die Quelle ist eine Leistung in W, die nur selten sendet; Portal oder Wallbox ordnen den Verbrauch einem anderen Zeitpunkt zu; das Gerät misst anders als dein Zähler; oder Startwerte, Einheit oder Gesamtstand passen nicht. Die Tabelle hilft dir, die Ursache zu finden.</p><table tabindex="0"><thead><tr><th>Ursache</th><th>Woran du sie erkennst</th><th>Was hilft</th></tr></thead><tbody><tr><td>Quelle ist eine Leistung (W), die nur alle paar Minuten sendet</td><td>Die Werte weichen stark ab, oft um ein Vielfaches</td><td>Den Gesamtzähler des Geräts in kWh nehmen oder das Gerät öfter senden lassen, z. B. alle 10 Sekunden</td></tr><tr><td>Leistungsquelle hatte eine Pause</td><td>Nach einem Ausfall fehlt Verbrauch oder ist viel zu hoch</td><td>Siehe <a href="#sourceanalytix-convert-watts-kwh">Pausen</a>, ab v0.7.0 „Maximale Lücke zwischen Leistungswerten (Minuten)&quot;</td></tr><tr><td>Anderer Zeitpunkt der Zuordnung</td><td>Tageswerte weichen ab, die Summe über mehrere Tage stimmt</td><td>Nichts, beide Werte stimmen. Vergleiche längere Zeiträume</td></tr><tr><td>Gerät misst anders als der Zähler des Netzbetreibers</td><td>Bezug und Einspeisung passen nicht zum Zähler im Keller</td><td>Den Zähler selbst auslesen, z. B. mit einem Lesekopf</td></tr><tr><td>Startwerte, Einheit oder Gesamtstand falsch</td><td>Werte sind negativ, viel zu hoch oder um einen festen Betrag versetzt</td><td>Siehe <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a></td></tr></tbody></table><h3 id="leistung-statt-zahlerstand" tabindex="-1">Leistung statt Zählerstand <a class="header-anchor" href="#leistung-statt-zahlerstand" aria-label="Permalink to &quot;Leistung statt Zählerstand&quot;">​</a></h3><p>Aus einer Leistung kann SourceAnalytix den Verbrauch nur schätzen. Jeder Wert gilt bis zum nächsten. Sendet ein Gerät nur alle 5 Minuten, rechnet SourceAnalytix jede kurze Spitze für die ganzen 5 Minuten. Bietet das Gerät einen Zählerstand in kWh, ist der genauer. Wie die Umrechnung arbeitet, steht unter <a href="#sourceanalytix-convert-watts-kwh">Wie rechnet SourceAnalytix Watt in kWh um?</a>.</p><h3 id="anderer-zeitpunkt-der-zuordnung" tabindex="-1">Anderer Zeitpunkt der Zuordnung <a class="header-anchor" href="#anderer-zeitpunkt-der-zuordnung" aria-label="Permalink to &quot;Anderer Zeitpunkt der Zuordnung&quot;">​</a></h3><p>SourceAnalytix bucht Verbrauch auf den Tag, an dem er gemessen wurde: Der Tageswert ist der Gesamtstand jetzt minus der Gesamtstand um 0:00 Uhr. Eine Wallbox oder evcc bucht dagegen oft einen ganzen Ladevorgang auf den Tag, an dem er endet. Hersteller-Portale rechnen teils mit 15-Minuten-Werten. Über Tage oder Monate gleicht sich das aus.</p><h3 id="gerat-misst-anders" tabindex="-1">Gerät misst anders <a class="header-anchor" href="#gerat-misst-anders" aria-label="Permalink to &quot;Gerät misst anders&quot;">​</a></h3><p>Ein Shelly 3EM zählt Bezug und Einspeisung je Phase. Der Zähler des Netzbetreibers verrechnet die Phasen miteinander. Bei Einspeisung auf einer Phase und Bezug auf einer anderen weichen beide deshalb ab, auch wenn SourceAnalytix richtig rechnet.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a></p><p><a id="sourceanalytix-convert-watts-kwh"></a></p><h2 id="wie-rechnet-sourceanalytix-watt-in-kwh-um" tabindex="-1">Wie rechnet SourceAnalytix Watt in kWh um? <a class="header-anchor" href="#wie-rechnet-sourceanalytix-watt-in-kwh-um" aria-label="Permalink to &quot;Wie rechnet SourceAnalytix Watt in kWh um?&quot;">​</a></h2><p><strong>Kurz:</strong> Mit jedem neuen Leistungswert rechnet SourceAnalytix die Energie seit dem vorigen Wert aus: vorige Leistung × Zeit seit dem vorigen Wert. Das ist eine linke Riemann-Summe. Mit „Mittelwert bei Leistung&quot; nimmt es stattdessen den Mittelwert aus vorigem und neuem Wert. Die Energie wird in die Zieleinheit umgerechnet und zum Gesamtstand addiert.</p><h3 id="die-formel" tabindex="-1">Die Formel <a class="header-anchor" href="#die-formel" aria-label="Permalink to &quot;Die Formel&quot;">​</a></h3><p>Energie in Wh = Leistung in W × Zeit in Stunden. Ein Beispiel mit drei Werten:</p><table tabindex="0"><thead><tr><th>Zeit</th><th>Wert</th><th>ohne Mittelwert</th><th>mit Mittelwert</th></tr></thead><tbody><tr><td>10:00</td><td>0 W</td><td>Ausgangspunkt</td><td>Ausgangspunkt</td></tr><tr><td>10:30</td><td>1.000 W</td><td>0 W × 0,5 h = 0 Wh</td><td>500 W × 0,5 h = 250 Wh</td></tr><tr><td>11:00</td><td>1.000 W</td><td>1.000 W × 0,5 h = 500 Wh</td><td>1.000 W × 0,5 h = 500 Wh</td></tr><tr><td>Summe</td><td></td><td>500 Wh = 0,5 kWh</td><td>750 Wh = 0,75 kWh</td></tr></tbody></table><p>Ohne Mittelwert passt die Rechnung zu Geräten, die abrupt schalten und nur bei einer Änderung senden. Mit Mittelwert passt sie zu Sensoren, deren Leistung gleichmäßig steigt und fällt und die regelmäßig senden.</p><h3 id="gerechnet-wird-nur-bei-einem-neuen-wert" tabindex="-1">Gerechnet wird nur bei einem neuen Wert <a class="header-anchor" href="#gerechnet-wird-nur-bei-einem-neuen-wert" aria-label="Permalink to &quot;Gerechnet wird nur bei einem neuen Wert&quot;">​</a></h3><p>SourceAnalytix rechnet, sobald die Quelle einen Wert schreibt, auch wenn er gleich bleibt. Maßgeblich ist der Zeitstempel des Werts. Ein Gerät, das nur bei einer Änderung sendet, wird trotzdem richtig gerechnet: Der letzte Wert gilt, bis ein neuer kommt.</p><h3 id="pausen" tabindex="-1">Pausen <a class="header-anchor" href="#pausen" aria-label="Permalink to &quot;Pausen&quot;">​</a></h3><ul><li><strong>Erster Wert:</strong> Nach der Aktivierung, nach einem Neustart von SourceAnalytix und nach einer Änderung der Einstellungen ist der erste Wert nur der Ausgangspunkt. Die Energie der Pause davor fehlt.</li><li><strong>Lange Stille bei laufender Instanz:</strong> Kommt lange kein neuer Wert, rechnet SourceAnalytix den letzten Wert über die ganze Pause hoch. <strong>Ab v0.7.0</strong> begrenzt „Maximale Lücke zwischen Leistungswerten (Minuten)&quot; das. Längere Pausen zählen dann als 0 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1266" target="_blank" rel="noreferrer">#1266</a>).</li><li><strong>Mitternacht:</strong> <strong>Ab v0.6.2</strong> bucht SourceAnalytix die Energie bis 0:00 Uhr dem alten Tag zu und rechnet im neuen Tag mit demselben Wert weiter. Ein Wert, der älter ist als der Vortag, wird nicht hochgerechnet (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1254" target="_blank" rel="noreferrer">#1254</a>).</li><li><strong>Negative Werte:</strong> Mit „Negative Werte ignorieren&quot; zählen sie als 0 W.</li></ul><p>Für Leistungsquellen gibt es keine Reset-Erkennung und keine Startwerte zum Eintragen. Ihr Gesamtstand beginnt mit der Aktivierung bei 0.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Zähler (kWh) oder Leistung (W)?</a> · <a href="./../anleitungen/quellen-und-einheiten#sourceanalytix-compute-consumption-meter-reading">Kann SourceAnalytix aus Leistung Verbrauch berechnen?</a></p><p><a id="consumption-calculated-currentyear-lower-than"></a></p><h2 id="wie-wird-der-verbrauch-berechnet-–-und-warum-ist-currentyear-niedriger-als-mein-zahlerstand" tabindex="-1">Wie wird der Verbrauch berechnet – und warum ist currentYear niedriger als mein Zählerstand? <a class="header-anchor" href="#wie-wird-der-verbrauch-berechnet-–-und-warum-ist-currentyear-niedriger-als-mein-zahlerstand" aria-label="Permalink to &quot;Wie wird der Verbrauch berechnet – und warum ist currentYear niedriger als mein Zählerstand?&quot;">​</a></h2><p><strong>Kurz:</strong> Das ist so gewollt. <code>currentYear.consumed.05_currentYear</code> ist der Verbrauch dieses Jahres, nicht der Zählerstand: Gesamtstand minus Startwert „Jahr&quot;. Den Zählerstand selbst findest du in <code>sourceanalytix.0.&lt;Gerät&gt;.cumulativeReading</code>.</p><p>Für jede Periode gilt dieselbe Formel: Verbrauch = Gesamtstand − Startwert der Periode. Der Startwert ist der Gesamtstand zu Beginn der Periode. SourceAnalytix setzt ihn bei jedem Periodenwechsel selbst, zum Beispiel am 1. Januar um 0:00 Uhr für „Jahr&quot;.</p><table tabindex="0"><thead><tr><th></th><th>Wert</th></tr></thead><tbody><tr><td>Gesamtstand (<code>cumulativeReading</code>)</td><td>12.480 kWh</td></tr><tr><td>Startwert „Jahr&quot; (Gesamtstand am 1. Januar)</td><td>11.900 kWh</td></tr><tr><td><code>05_currentYear</code></td><td>580 kWh</td></tr></tbody></table><p>Hast du SourceAnalytix erst im Laufe des Jahres aktiviert, ist der Startwert „Jahr&quot; der Gesamtstand bei der Aktivierung. Das Jahr zählt dann ab diesem Tag. Soll es ab dem 1. Januar zählen, trägst du den Zählerstand vom 1. Januar als Startwert ein, siehe <a href="./../erste-schritte/erster-zaehler#start-values-unit">Was trage ich bei den Startwerten ein?</a>.</p><p>Den Zählerstand am Ende jeder Periode speichert SourceAnalytix unter <code>currentYear.meterReadings</code>, wenn „Zählerstände speichern&quot; an ist.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/states-und-meldungen#meter-readings-cumulative">Zählerstände je Periode (meterReadings)</a> · <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Wo finde ich meine Werte?</a></p>',40)])])}const m=t(i,[["render",d]]);export{g as __pageData,m as default};
